practice.starterCode:
PRAGMA foreign_keys = ON;

CREATE TABLE proj25_accounts (
  account_id INTEGER PRIMARY KEY,
  account_label TEXT NOT NULL,
  balance_cents INTEGER NOT NULL CHECK (balance_cents >= 0)
);

CREATE TABLE proj25_transfer_requests (
  idempotency_key TEXT PRIMARY KEY,
  source_account_id INTEGER NOT NULL REFERENCES proj25_accounts(account_id),
  destination_account_id INTEGER NOT NULL REFERENCES proj25_accounts(account_id),
  amount_cents INTEGER NOT NULL CHECK (amount_cents > 0),
  CHECK (source_account_id <> destination_account_id)
);

CREATE TABLE proj25_ledger (
  entry_id INTEGER PRIMARY KEY,
  account_id INTEGER NOT NULL REFERENCES proj25_accounts(account_id),
  transaction_ref TEXT NOT NULL,
  entry_type TEXT NOT NULL CHECK (entry_type IN ('opening','debit','credit','reversal')),
  amount_cents INTEGER NOT NULL CHECK (amount_cents <> 0),
  created_at TEXT NOT NULL,
  UNIQUE (transaction_ref, account_id, entry_type),
  CHECK (
    (entry_type IN ('opening','credit','reversal') AND amount_cents > 0)
    OR (entry_type = 'debit' AND amount_cents < 0)
  )
);

INSERT INTO proj25_accounts VALUES
  (1, 'Asha', 10000),
  (2, 'Bilal', 5000);

INSERT INTO proj25_ledger VALUES
  (1, 1, 'OPEN-1', 'opening', 10000, '2026-11-22T09:00:00Z'),
  (2, 2, 'OPEN-2', 'opening', 5000, '2026-11-22T09:00:00Z');

-- The unique idempotency key represents one client transfer request.
BEGIN;
INSERT INTO proj25_transfer_requests
  VALUES ('REQ-1001', 1, 2, 2500);
UPDATE proj25_accounts
  SET balance_cents = balance_cents - 2500
  WHERE account_id = 1 AND balance_cents >= 2500;
UPDATE proj25_accounts
  SET balance_cents = balance_cents + 2500
  WHERE account_id = 2;
INSERT INTO proj25_ledger VALUES
  (3, 1, 'TX-5001', 'debit', -2500, '2026-11-22T09:05:00Z'),
  (4, 2, 'TX-5001', 'credit', 2500, '2026-11-22T09:05:00Z');
COMMIT;

SELECT account_id, balance_cents
FROM proj25_accounts
ORDER BY account_id;

SELECT a.account_id, a.balance_cents,
       SUM(l.amount_cents) AS ledger_balance_cents
FROM proj25_accounts AS a
JOIN proj25_ledger AS l ON l.account_id = a.account_id
GROUP BY a.account_id, a.balance_cents
ORDER BY a.account_id;

